1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useParams } from 'react-router-dom';
3	import {
4	  login, getGarcomToken, setGarcomToken, clearGarcomToken, getMe,
5	  getMesas, getProdutos, getMinhasComandas, getComanda, getItensProntos,
6	  abrirComanda, adicionarItens, editarItem, removerItem, enviarItens, fecharComanda,
7	  registrarPagamento, editarClienteComanda, excluirComanda,
8	} from '../../services/garcomService';
9	import { printTicketSetor } from '../../utils/printComanda';
10	import { getAcompanharUrls } from '../../utils/mesaAcompanharUrl';
11	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
12	import Icon from '../../components/AppIcon';
13	
14	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
15	const PAGAMENTO_LABEL = { pix: 'PIX', credit_card: 'Cartão crédito', debit_card: 'Cartão débito', cash: 'Dinheiro' };
16	
17	const MESA_STATUS_COR = {
18	  livre: 'bg-emerald-100 text-emerald-700 border-emerald-200',
19	  ocupada: 'bg-orange-100 text-orange-700 border-orange-200',
20	  aguardando_pagamento: 'bg-blue-100 text-blue-700 border-blue-200',
21	  bloqueada: 'bg-zinc-200 text-zinc-500 border-zinc-300',
22	};
23	const MESA_STATUS_LABEL = { livre: 'Livre', ocupada: 'Ocupada', aguardando_pagamento: 'Aguard. pagamento', bloqueada: 'Bloqueada' };
24	const MESA_OCUPADA_OUTRO_COR = 'bg-purple-100 text-purple-700 border-purple-200';
25	
26	const responsavelMesa = (comanda) =>
27	  comanda?.garcons?.nome ?? (comanda?.aberto_por_nome ? `Caixa: ${comanda.aberto_por_nome}` : null);
28	
29	const GarcomLogin = ({ loginKey, onLogin }) => {
30	  const [password, setPassword] = useState('');
31	  const [erro, setErro] = useState(null);
32	  const [loading, setLoading] = useState(false);
33	
34	  const handleSubmit = async (e) => {
35	    e.preventDefault();
36	    setErro(null);
37	    setLoading(true);
38	    try {
39	      const { token } = await login(loginKey, password);
40	      setGarcomToken(token);
41	      onLogin();
42	    } catch (err) {
43	      setErro(err.message ?? 'Senha inválida.');
44	    } finally {
45	      setLoading(false);
46	    }
47	  };
48	
49	  return (
50	    <div className="min-h-screen bg-[#F4F4F5] flex items-center justify-center p-4">
51	      <div className="bg-white rounded-2xl border border-[#E4E4E7] p-6 w-full max-w-sm shadow-lg">
52	        <div className="text-center mb-6">
53	          <div className="w-14 h-14 bg-[#FF441F]/10 rounded-2xl flex items-center justify-center mx-auto mb-3">
54	            <Icon name="UtensilsCrossed" size={28} className="text-[#FF441F]" />
55	          </div>
56	          <h1 className="text-lg font-black text-[#18181B]">Portal do Garçom</h1>
57	          <p className="text-sm text-[#71717A] mt-1">Digite sua senha pra entrar</p>
58	        </div>
59	        <form onSubmit={handleSubmit} className="space-y-3">
60	          <input
61	            type="password"
62	            value={password}
63	            onChange={(e) => setPassword(e.target.value)}
64	            placeholder="Senha"
65	            autoFocus
66	            required
67	            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-3 text-sm focus:outline-none focus:border-[#FF441F]"
68	          />
69	          {erro && <p className="text-xs text-red-600">{erro}</p>}
70	          <button type="submit" disabled={loading}
71	            className="w-full py-3 bg-[#FF441F] text-white font-bold rounded-xl hover:bg-[#E63A19] disabled:opacity-50 text-sm">
72	            {loading ? 'Entrando...' : 'Entrar'}
73	          </button>
74	        </form>
75	      </div>
76	    </div>
77	  );
78	};
79	
80	const AbrirComandaModal = ({ mesa, onFechar, onAberta }) => {
81	  const [nome, setNome] = useState('');
82	  const [telefone, setTelefone] = useState('');
83	  const [erro, setErro] = useState(null);
84	  const [salvando, setSalvando] = useState(false);
85	
86	  const submit = async (e) => {
87	    e.preventDefault();
88	    setErro(null);
89	    setSalvando(true);
90	    try {
91	      const comanda = await abrirComanda({ mesa_id: mesa?.id ?? null, cliente_nome: nome.trim(), cliente_telefone: telefone.trim() });
92	      onAberta(comanda);
93	    } catch (err) {
94	      setErro(err.message ?? 'Não foi possível abrir a comanda.');
95	    } finally {
96	      setSalvando(false);
97	    }
98	  };
99	
100	  return (
101	    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-50 p-4">
102	      <div className="bg-white rounded-2xl p-6 w-full max-w-sm shadow-2xl">
103	        <h2 className="text-base font-bold text-[#18181B] mb-1">
104	          {mesa ? `Abrir Mesa ${mesa.numero}` : 'Abrir comanda avulsa'}
105	        </h2>
106	        <p className="text-xs text-[#71717A] mb-4">Nome e telefone do cliente são obrigatórios antes de vender.</p>
107	        <form onSubmit={submit} className="space-y-3">
108	          <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Nome do cliente" required
109	            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
110	          <input value={telefone} onChange={(e) => setTelefone(e.target.value)} placeholder="Telefone do cliente" required
111	            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
112	          {erro && <p className="text-xs text-red-600">{erro}</p>}
113	          <div className="flex gap-2 pt-1">
114	            <button type="button" onClick={onFechar}
115	              className="flex-1 py-2.5 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A] hover:bg-[#F4F4F5]">
116	              Cancelar
117	            </button>
118	            <button type="submit" disabled={salvando}
119	              className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
120	              {salvando ? 'Abrindo...' : 'Abrir'}
121	            </button>
122	          </div>
123	        </form>
124	      </div>
125	    </div>
126	  );
127	};
128	
129	const EditarClienteModal = ({ comanda, onFechar, onEditado }) => {
130	  const [nome, setNome] = useState(comanda.cliente_mesa_nome ?? '');
131	  const [telefone, setTelefone] = useState(comanda.cliente_mesa_telefone ?? '');
132	  const [erro, setErro] = useState(null);
133	  const [salvando, setSalvando] = useState(false);
134	
135	  const submit = async (e) => {
136	    e.preventDefault();
137	    setErro(null);
138	    setSalvando(true);
139	    try {
140	      await editarClienteComanda(comanda.id, nome.trim(), telefone.trim());
141	      await onEditado();
142	      onFechar();
143	    } catch (err) {
144	      setErro(err.message ?? 'Não foi possível salvar.');
145	    } finally {
146	      setSalvando(false);
147	    }
148	  };
149	
150	  return (
151	    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-[60] p-4">
152	      <div className="bg-white rounded-2xl p-6 w-full max-w-sm shadow-2xl">
153	        <h2 className="text-base font-bold text-[#18181B] mb-1">Editar dados do cliente</h2>
154	        <p className="text-xs text-[#71717A] mb-4">Corrige nome ou telefone digitados errado na abertura.</p>
155	        <form onSubmit={submit} className="space-y-3">
156	          <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Nome do cliente" required
157	            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
158	          <input value={telefone} onChange={(e) => setTelefone(e.target.value)} placeholder="Telefone do cliente" required
159	            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
160	          {erro && <p className="text-xs text-red-600">{erro}</p>}
161	          <div className="flex gap-2 pt-1">
162	            <button type="button" onClick={onFechar}
163	              className="flex-1 py-2.5 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A] hover:bg-[#F4F4F5]">
164	              Cancelar
165	            </button>
166	            <button type="submit" disabled={salvando}
167	              className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
168	              {salvando ? 'Salvando...' : 'Salvar'}
169	            </button>
170	          </div>
171	        </form>
172	      </div>
173	    </div>
174	  );
175	};
176	
177	const FecharComandaModal = ({ comanda, onFechar, onFechada }) => {
178	  const [forma, setForma] = useState('pix');
179	  const [erro, setErro] = useState(null);
180	  const [salvando, setSalvando] = useState(false);
181	
182	  const confirmar = async () => {
183	    setErro(null);
184	    setSalvando(true);
185	    try {
186	      await fecharComanda(comanda.id, forma);
187	      onFechada();
188	    } catch (err) {
189	      setErro(err.message ?? 'Não foi possível fechar a comanda.');
190	    } finally {
191	      setSalvando(false);
192	    }
193	  };
194	
195	  return (
196	    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-50 p-4">
197	      <div className="bg-white rounded-2xl p-6 w-full max-w-sm shadow-2xl">
198	        <h2 className="text-base font-bold text-[#18181B] mb-1">Fechar comanda</h2>
199	        <p className="text-xs text-[#71717A] mb-4">
200	          A mesa fica bloqueada aguardando pagamento — quem finaliza e emite o recibo é o caixa.
201	        </p>
202	        <label className="text-xs text-[#71717A]">Forma de pagamento informada pelo cliente</label>
203	        <select value={forma} onChange={(e) => setForma(e.target.value)}
204	          className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm mt-1 mb-3">
205	          <option value="pix">PIX</option>
206	          <option value="credit_card">Cartão de crédito</option>
207	          <option value="debit_card">Cartão de débito</option>
208	          <option value="cash">Dinheiro</option>
209	        </select>
210	        {erro && <p className="text-xs text-red-600 mb-2">{erro}</p>}
211	        <div className="flex gap-2">
212	          <button onClick={onFechar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A] hover:bg-[#F4F4F5]">
213	            Voltar
214	          </button>
215	          <button onClick={confirmar} disabled={salvando}
216	            className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
217	            {salvando ? 'Fechando...' : 'Fechar comanda'}
218	          </button>
219	        </div>
220	      </div>
221	    </div>
222	  );
223	};
224	
225	const QuickAddModal = ({ produto, onFechar, onConfirmar }) => {
226	  const [quantidade, setQuantidade] = useState(1);
227	  const [observacao, setObservacao] = useState('');
228	  const [salvando, setSalvando] = useState(false);
229	
230	  const confirmar = async () => {
231	    setSalvando(true);
232	    try {
233	      await onConfirmar({ product_id: produto.id, quantity: quantidade, observacao: observacao.trim() || undefined });
234	    } finally {
235	      setSalvando(false);
236	    }
237	  };
238	
239	  return (
240	    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-[60] p-4">
241	      <div className="bg-white rounded-2xl w-full max-w-sm p-5 shadow-2xl">
242	        <div className="flex items-center gap-3 mb-4">
243	          <div className="w-14 h-14 rounded-xl overflow-hidden bg-[#F4F4F5] flex-shrink-0">
244	            {produto.image_url
245	              ? <img src={produto.image_url} alt="" className="w-full h-full object-cover" />
246	              : <div className="w-full h-full flex items-center justify-center"><Icon name="UtensilsCrossed" size={20} className="text-[#A1A1AA]" /></div>}
247	          </div>
248	          <div className="min-w-0">
249	            <p className="text-sm font-bold text-[#18181B] truncate">{produto.name}</p>
250	            <p className="text-xs text-[#71717A]">{fmt(produto.price)}</p>
251	          </div>
252	        </div>
253	
254	        <label className="text-xs text-[#71717A]">Quantidade</label>
255	        <div className="flex items-center gap-3 mt-1 mb-3">
256	          <button onClick={() => setQuantidade((q) => Math.max(1, q - 1))}
257	            className="w-10 h-10 rounded-xl border border-[#E4E4E7] flex items-center justify-center text-lg font-bold text-[#27272A]">−</button>
258	          <span className="text-lg font-bold text-[#18181B] w-8 text-center">{quantidade}</span>
259	          <button onClick={() => setQuantidade((q) => q + 1)}
260	            className="w-10 h-10 rounded-xl border border-[#E4E4E7] flex items-center justify-center text-lg font-bold text-[#27272A]">+</button>
261	        </div>
262	
263	        <label className="text-xs text-[#71717A]">Observação (opcional)</label>
264	        <textarea value={observacao} onChange={(e) => setObservacao(e.target.value)} rows={2}
265	          placeholder="Ex: sem cebola, ponto da carne..."
266	          className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm mt-1 mb-4 resize-none" />
267	
268	        <div className="flex gap-2">
269	          <button onClick={onFechar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A]">
270	            Cancelar
271	          </button>
272	          <button onClick={confirmar} disabled={salvando}
273	            className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
274	            {salvando ? 'Adicionando...' : 'Adicionar'}
275	          </button>
276	        </div>
277	      </div>
278	    </div>
279	  );
280	};
281	
282	const ProdutoPickerModal = ({ produtos, onFechar, onAdicionado }) => {
283	  const [busca, setBusca] = useState('');
284	  const [categoria, setCategoria] = useState('todas');
285	  const [produtoAtivo, setProdutoAtivo] = useState(null);
286	
287	  const categorias = ['todas', ...new Set(produtos.map((p) => p.category_name ?? 'Outros'))];
288	  const filtrados = produtos.filter((p) => {
289	    const bateBusca = p.name.toLowerCase().includes(busca.toLowerCase());
290	    const bateCategoria = categoria === 'todas' || (p.category_name ?? 'Outros') === categoria;
291	    return bateBusca && bateCategoria;
292	  });
293	
294	  return (
295	    <div className="fixed inset-0 bg-white z-50 flex flex-col">
296	      <div className="p-4 border-b border-[#E4E4E7] sticky top-0 bg-white max-w-2xl w-full mx-auto">
297	        <div className="flex items-center gap-2 mb-3">
298	          <button onClick={onFechar} className="p-1 text-[#71717A]"><Icon name="ArrowLeft" size={20} /></button>
299	          <h2 className="text-base font-bold text-[#18181B]">Adicionar produto</h2>
300	        </div>
301	        <div className="relative">
302	          <Icon name="Search" size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#A1A1AA]" />
303	          <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar produto..." autoFocus
304	            className="w-full border border-[#E4E4E7] rounded-xl pl-9 pr-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
305	        </div>
306	        <div className="flex gap-1.5 mt-3 overflow-x-auto pb-1">
307	          {categorias.map((c) => (
308	            <button key={c} onClick={() => setCategoria(c)}
309	              className={`px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap flex-shrink-0 ${
310	                categoria === c ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] text-[#71717A]'
311	              }`}>
312	              {c === 'todas' ? 'Todas' : c}
313	            </button>
314	          ))}
315	        </div>
316	      </div>
317	
318	      <div className="flex-1 overflow-y-auto p-4 max-w-2xl w-full mx-auto space-y-2">
319	        {filtrados.map((p) => (
320	          <button key={p.id} onClick={() => setProdutoAtivo(p)}
321	            className="w-full bg-white border border-[#E4E4E7] rounded-xl p-2.5 flex items-center gap-3 text-left active:scale-[0.98] transition-transform">
322	            <div className="w-12 h-12 rounded-lg overflow-hidden bg-[#F4F4F5] flex-shrink-0">
323	              {p.image_url
324	                ? <img src={p.image_url} alt="" className="w-full h-full object-cover" />
325	                : <div className="w-full h-full flex items-center justify-center"><Icon name="UtensilsCrossed" size={18} className="text-[#A1A1AA]" /></div>}
326	            </div>
327	            <div className="min-w-0 flex-1">
328	              <p className="text-sm font-semibold text-[#18181B] truncate">{p.name}</p>
329	              <p className="text-xs text-[#71717A]">{fmt(p.price)}</p>
330	            </div>
331	            <Icon name="Plus" size={18} className="text-[#FF441F] flex-shrink-0" />
332	          </button>
333	        ))}
334	        {filtrados.length === 0 && <p className="text-sm text-[#A1A1AA] text-center py-6">Nenhum produto encontrado.</p>}
335	      </div>
336	
337	      {produtoAtivo && (
338	        <QuickAddModal
339	          produto={produtoAtivo}
340	          onFechar={() => setProdutoAtivo(null)}
341	          onConfirmar={async (item) => { await onAdicionado(item); setProdutoAtivo(null); }}
342	        />
343	      )}
344	    </div>
345	  );
346	};
347	
348	const PagamentoParcial = ({ comanda, onRegistrado, podePagamentoParcial }) => {
349	  const [valor, setValor] = useState('');
350	  const [forma, setForma] = useState('pix');
351	  const [valorRecebido, setValorRecebido] = useState('');
352	  const [erro, setErro] = useState(null);
353	  const [salvando, setSalvando] = useState(false);
354	
355	  const saldo = comanda.saldo?.saldo ?? 0;
356	  const troco = forma === 'cash' && valorRecebido ? Number(valorRecebido) - Number(valor || 0) : null;
357	
358	  const registrar = async () => {
359	    const v = Number(valor);
360	    if (!v || v <= 0) return;
361	    if (forma === 'cash' && valorRecebido && Number(valorRecebido) < v) {
362	      setErro('Valor recebido não pode ser menor que o valor a pagar.');
363	      return;
364	    }
365	    setErro(null);
366	    setSalvando(true);
367	    try {
368	      await registrarPagamento(comanda.id, v, forma, forma === 'cash' && valorRecebido ? Number(valorRecebido) : undefined);
369	      setValor('');
370	      setValorRecebido('');
371	      await onRegistrado();
372	    } catch (err) {
373	      setErro(err.message ?? 'Não foi possível registrar o pagamento.');
374	    } finally {
375	      setSalvando(false);
376	    }
377	  };
378	
379	  return (
380	    <div className="bg-white rounded-xl border border-[#E4E4E7] p-3 space-y-2">
381	      <div className="flex justify-between text-sm">
382	        <span className="text-[#71717A]">Saldo devedor</span>
383	        <strong className={saldo > 0.01 ? 'text-[#FF441F]' : 'text-emerald-600'}>{fmt(saldo)}</strong>
384	      </div>
385	      {(comanda.pagamentos ?? []).length > 0 && (
386	        <div className="space-y-0.5">
387	          {comanda.pagamentos.map((p) => (
388	            <p key={p.id} className="text-xs text-[#71717A] flex justify-between">
389	              <span>{PAGAMENTO_LABEL[p.forma_pagamento] ?? p.forma_pagamento} ({p.origem === 'garcom' ? 'garçom' : 'caixa'})</span>
390	              <span>{fmt(p.valor)}</span>
391	            </p>
392	          ))}
393	        </div>
394	      )}
395	      {saldo > 0.01 && podePagamentoParcial && (
396	        <div className="space-y-1.5 pt-1">
397	          <div className="flex items-center gap-1.5">
398	            <input type="number" value={valor} onChange={(e) => setValor(e.target.value)} placeholder="Valor"
399	              className="w-20 border border-[#E4E4E7] rounded-lg px-2 py-1.5 text-xs" />
400	            <select value={forma} onChange={(e) => setForma(e.target.value)}
401	              className="flex-1 border border-[#E4E4E7] rounded-lg px-2 py-1.5 text-xs">
402	              <option value="pix">PIX</option>
403	              <option value="credit_card">Cartão de crédito</option>
404	              <option value="debit_card">Cartão de débito</option>
405	              <option value="cash">Dinheiro</option>
406	            </select>
407	            <button onClick={registrar} disabled={salvando || !valor}
408	              className="px-2.5 py-1.5 bg-zinc-800 text-white rounded-lg text-xs font-bold disabled:opacity-40 flex-shrink-0">
409	              Pagar
410	            </button>
411	          </div>
412	          {forma === 'cash' && (
413	            <div className="flex items-center gap-1.5">
414	              <input type="number" value={valorRecebido} onChange={(e) => setValorRecebido(e.target.value)}
415	                placeholder="Valor recebido do cliente"
416	                className="flex-1 border border-[#E4E4E7] rounded-lg px-2 py-1.5 text-xs" />
417	              {troco !== null && (
