1	import { BadRequestException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	
4	export interface AbrirComandaBody {
5	  mesa_id?: number;
6	  cliente_nome: string;
7	  cliente_telefone: string;
8	}
9	
10	export interface ItemComandaBody {
11	  product_id: number;
12	  quantity: number;
13	  observacao?: string;
14	}
15	
16	@Injectable()
17	export class SalaoService {
18	  constructor(private supabase: SupabaseService) {}
19	
20	  async mesas(restaurantId: number) {
21	    const { data: mesas, error } = await this.supabase.client
22	      .from('mesas')
23	      .select('id, numero, nome, status')
24	      .eq('restaurant_id', restaurantId)
25	      .order('numero', { ascending: true });
26	    if (error) throw error;
27	
28	    // Precisa saber de quem é a comanda em cada mesa ocupada — o garçom só pode
29	    // clicar/entrar se a comanda for dele (ver garcom-portal, grid de mesas).
30	    const { data: comandas } = await this.supabase.client
31	      .from('orders')
32	      .select('id, mesa_id, garcom_id, cliente_mesa_nome, total, garcons(nome), aberto_por_nome, conferencia_solicitada_em')
33	      .eq('restaurant_id', restaurantId)
34	      .eq('canal', 'presencial')
35	      .in('status', ['aberta', 'fechada_garcom'])
36	      .not('mesa_id', 'is', null);
37	
38	    const comandaPorMesa = new Map((comandas ?? []).map((c: any) => [c.mesa_id, c]));
39	
40	    return (mesas ?? []).map((m: any) => ({ ...m, comanda: comandaPorMesa.get(m.id) ?? null }));
41	  }
42	
43	  // Acompanhamento público via QR (ideia 13) — sem auth, só o essencial pro cliente da mesa.
44	  async acompanharPorToken(token: string) {
45	    const { data: comanda } = await this.supabase.client
46	      .from('orders')
47	      .select('id, status, conferencia_solicitada_em, mesas(numero, nome), restaurants(name)')
48	      .eq('tracking_token', token)
49	      .eq('canal', 'presencial')
50	      .maybeSingle();
51	    if (!comanda) throw new NotFoundException('Comanda não encontrada');
52	
53	    const { data: itens } = await this.supabase.client
54	      .from('order_items')
55	      .select('quantity, status, enviado_em, preparando_em, products(name)')
56	      .eq('order_id', comanda.id);
57	
58	    return {
59	      restaurante: (comanda as any).restaurants?.name,
60	      mesa: (comanda as any).mesas ? `Mesa ${(comanda as any).mesas.numero}` : null,
61	      status: comanda.status,
62	      conferencia_solicitada_em: (comanda as any).conferencia_solicitada_em,
63	      itens: (itens ?? []).map((i: any) => ({
64	        quantity: i.quantity,
65	        status: i.status,
66	        enviado_em: i.enviado_em,
67	        preparando_em: i.preparando_em,
68	        product_name: i.products?.name,
69	      })),
70	    };
71	  }
72	
73	  async produtos(restaurantId: number) {
74	    const { data, error } = await this.supabase.client
75	      .from('products')
76	      .select('id, name, price, image_url, category_id, categories(name)')
77	      .eq('restaurant_id', restaurantId)
78	      .eq('is_active', true)
79	      .order('name', { ascending: true });
80	    if (error) throw error;
81	    return (data ?? []).map((p: any) => ({ ...p, category_name: p.categories?.name ?? 'Outros' }));
82	  }
83	
84	  private async garantirComandaDoGarcom(comandaId: number, garcomId: number) {
85	    const { data } = await this.supabase.client
86	      .from('orders')
87	      .select('id, status, restaurant_id, mesa_id, garcom_id, numero_comanda, cliente_mesa_nome, cliente_mesa_telefone, tracking_token, mesas(numero, nome), garcons(nome)')
88	      .eq('id', comandaId)
89	      .eq('canal', 'presencial')
90	      .maybeSingle();
91	    if (!data) throw new NotFoundException('Comanda não encontrada');
92	    if (data.garcom_id !== garcomId) throw new ForbiddenException('Comanda não pertence a este garçom');
93	    return data;
94	  }
95	
96	  // Saldo devedor considerando pagamentos parciais já registrados (garçom ou caixa).
97	  async saldoDevedor(comandaId: number) {
98	    const { data: itens } = await this.supabase.client.from('order_items').select('quantity, unit_price').eq('order_id', comandaId);
99	    const { data: comanda } = await this.supabase.client
100	      .from('orders')
101	      .select('desconto_valor, acrescimo_valor')
102	      .eq('id', comandaId)
103	      .maybeSingle();
104	    const { data: pagamentos } = await this.supabase.client.from('comanda_pagamentos').select('valor').eq('order_id', comandaId);
105	
106	    const subtotal = (itens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
107	    const totalFinal = subtotal - (comanda?.desconto_valor ?? 0) + (comanda?.acrescimo_valor ?? 0);
108	    const totalPago = (pagamentos ?? []).reduce((acc: number, p: any) => acc + p.valor, 0);
109	
110	    return {
111	      subtotal: parseFloat(subtotal.toFixed(2)),
112	      total: parseFloat(totalFinal.toFixed(2)),
113	      total_pago: parseFloat(totalPago.toFixed(2)),
114	      saldo: parseFloat((totalFinal - totalPago).toFixed(2)),
115	    };
116	  }
117	
118	  // Lança uma saída automática no caixa aberto do restaurante — usado pra registrar troco
119	  // dado e gorjeta paga em dinheiro, sem o caixa precisar lançar isso manualmente depois.
120	  async registrarSaidaCaixa(restaurantId: number, descricao: string, valor: number, tipo: 'troco' | 'gorjeta') {
121	    if (!(valor > 0)) return;
122	    const { data: caixa } = await this.supabase.client
123	      .from('caixas')
124	      .select('id, saidas')
125	      .eq('restaurant_id', restaurantId)
126	      .eq('status', 'aberto')
127	      .maybeSingle();
128	    if (!caixa) return; // sem caixa aberto: melhor não travar o pagamento por isso
129	
130	    const saidas = (caixa.saidas ?? []) as any[];
131	    const nova = { descricao, valor, meio: 'dinheiro', tipo, criado_em: new Date().toISOString() };
132	    await this.supabase.client.from('caixas').update({ saidas: [...saidas, nova] }).eq('id', caixa.id);
133	  }
134	
135	  // Registra um pagamento parcial — não fecha a comanda sozinho, só abate do saldo devedor.
136	  // Chamado tanto pelo garçom (informar forma de pagamento) quanto pelo caixa (conferência).
137	  // Em dinheiro, valorRecebido é o que o cliente entregou — troco é calculado e vira saída
138	  // automática no caixa (ver registrarSaidaCaixa).
139	  async registrarPagamento(
140	    comandaId: number,
141	    origem: 'garcom' | 'estabelecimento',
142	    valor: number,
143	    formaPagamento: string,
144	    restaurantId: number,
145	    valorRecebido?: number,
146	    identificador?: string,
147	    taxaCartaoValor?: number,
148	  ) {
149	    if (!valor || valor <= 0) throw new BadRequestException('Valor precisa ser maior que zero');
150	    if (!formaPagamento) throw new BadRequestException('Informe a forma de pagamento');
151	
152	    let troco: number | null = null;
153	    if (formaPagamento === 'cash' && valorRecebido !== undefined) {
154	      if (valorRecebido < valor) throw new BadRequestException('Valor recebido não pode ser menor que o valor a pagar');
155	      troco = parseFloat((valorRecebido - valor).toFixed(2));
156	    }
157	
158	    const { error } = await this.supabase.client
159	      .from('comanda_pagamentos')
160	      .insert({
161	        order_id: comandaId, valor, forma_pagamento: formaPagamento, origem,
162	        valor_recebido: valorRecebido ?? null, troco, taxa_cartao_valor: taxaCartaoValor || null,
163	      });
164	    if (error) throw error;
165	
166	    if (troco && troco > 0) {
167	      await this.registrarSaidaCaixa(restaurantId, `Troco${identificador ? ` - ${identificador}` : ''}`, troco, 'troco');
168	    }
169	
170	    return this.saldoDevedor(comandaId);
171	  }
172	
173	  // Permissão default true (opt-out) — preserva o comportamento de quem já usava
174	  // isso sem restrição antes da permissão existir; dono desativa por garçom se quiser.
175	  async registrarPagamentoComoGarcom(comandaId: number, garcomId: number, valor: number, formaPagamento: string, podePagamentoParcial = true, valorRecebido?: number) {
176	    if (!podePagamentoParcial) throw new ForbiddenException('Você não tem permissão para registrar pagamento parcial');
177	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
178	    if (!['aberta', 'fechada_garcom'].includes(comanda.status)) {
179	      throw new BadRequestException('Comanda já foi paga ou cancelada');
180	    }

